package com.rotarypumpers.meraki;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;
import com.journeyapps.barcodescanner.*;import com.google.zxing.BarcodeFormat;import java.util.*;
/** In-app camera only. No image is saved; decoded data is returned only to our caller. */
public final class PairingScanActivity extends Activity {
 static final String RESULT="pairing_qr";private static final int CAMERA=12;
 private DecoratedBarcodeView scanner;private TextView status;private Button allow;private boolean delivered,requesting,asked;
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 @Override public void onCreate(Bundle state){super.onCreate(state);asked=state!=null&&state.getBoolean("camera_permission_asked",false);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);setResult(RESULT_CANCELED);
  LinearLayout root=new LinearLayout(this);boolean landscape=getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE;root.setOrientation(landscape?0:1);root.setBackgroundColor(0xff140f0b);root.setPadding(dp(14),dp(12),dp(14),dp(12));
  scanner=new DecoratedBarcodeView(this);scanner.getBarcodeView().setDecoderFactory(new DefaultDecoderFactory(Collections.singleton(BarcodeFormat.QR_CODE)));scanner.setStatusText("");
  scanner.getBarcodeView().addStateListener(new CameraPreview.StateListener(){public void previewSized(){}public void previewStarted(){}public void previewStopped(){}public void cameraClosed(){}public void cameraError(Exception e){status.setText("Camera could not start. Close other camera apps and try again, or use a pairing file.");allow.setText("Try camera again");allow.setVisibility(View.VISIBLE);}});
  LinearLayout controls=new LinearLayout(this);controls.setOrientation(1);
  ScrollView info=new ScrollView(this);LinearLayout copy=new LinearLayout(this);copy.setOrientation(1);TextView title=text("Scan pairing code",23);title.setTypeface(null,1);copy.addView(title);copy.addView(text("Point at the pairing code displayed on your computer. Keep the whole square in view.",16));status=text("Camera opens only for this scan. Nothing is saved until you confirm the machine.",14);copy.addView(status);info.addView(copy);
  controls.addView(info,new LinearLayout.LayoutParams(-1,0,1));
  allow=button("Allow camera",()->permission());allow.setVisibility(View.GONE);controls.addView(allow,new LinearLayout.LayoutParams(-1,dp(52)));Button cancel=button("Cancel scan",()->finish());controls.addView(cancel,new LinearLayout.LayoutParams(-1,dp(52)));
  if(landscape){root.addView(scanner,new LinearLayout.LayoutParams(0,-1,3));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-1,2);cp.leftMargin=dp(14);root.addView(controls,cp);}else{root.addView(scanner,new LinearLayout.LayoutParams(-1,0,3));root.addView(controls,new LinearLayout.LayoutParams(-1,0,2));}
  setContentView(root);scanner.decodeContinuous(new BarcodeCallback(){public void barcodeResult(BarcodeResult result){deliver(result.getText());}public void possibleResultPoints(List<com.google.zxing.ResultPoint> points){}});
 }
 private TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(0xfff6ead7);v.setPadding(dp(4),dp(5),dp(4),dp(5));return v;}
 private Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextSize(16);b.setAllCaps(false);b.setTextColor(0xff23351b);GradientDrawable bg=new GradientDrawable();bg.setColor(0xffb2ca99);bg.setCornerRadius(dp(10));b.setBackground(bg);b.setOnClickListener(v->r.run());return b;}
 @Override protected void onResume(){super.onResume();if(delivered)return;if(!getPackageManager().hasSystemFeature(PackageManager.FEATURE_CAMERA_ANY)){status.setText("No camera is available. Cancel and choose Import pairing file in Machine connection.");allow.setVisibility(View.GONE);return;}if(checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED){allow.setVisibility(View.GONE);scanner.resume();}else if(!requesting&&!asked)permission();else if(!requesting){status.setText("Camera permission is needed to scan. You can also cancel and choose Import pairing file.");allow.setText(shouldShowRequestPermissionRationale(Manifest.permission.CAMERA)?"Allow camera":"Open camera settings");allow.setVisibility(View.VISIBLE);}}
 private void permission(){if(delivered)return;if(checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED){allow.setVisibility(View.GONE);scanner.resume();return;}if(requesting)return;if(asked&&!shouldShowRequestPermissionRationale(Manifest.permission.CAMERA)){startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+getPackageName())));return;}asked=true;requesting=true;requestPermissions(new String[]{Manifest.permission.CAMERA},CAMERA);}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code!=CAMERA)return;requesting=false;if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED){allow.setVisibility(View.GONE);scanner.resume();}else{status.setText("Camera permission was not granted. You can cancel and import a pairing file or enter details instead. If blocked, allow Camera in Android’s app settings.");allow.setText(shouldShowRequestPermissionRationale(Manifest.permission.CAMERA)?"Allow camera":"Open camera settings");allow.setVisibility(View.VISIBLE);}}
 @Override protected void onSaveInstanceState(Bundle out){out.putBoolean("camera_permission_asked",asked);super.onSaveInstanceState(out);}
 @Override protected void onPause(){scanner.pause();super.onPause();}
 void deliver(String raw){if(delivered||raw==null)return;delivered=true;scanner.pause();if(raw.length()<=2048)setResult(RESULT_OK,new Intent().putExtra(RESULT,raw));else setResult(RESULT_OK,new Intent().putExtra(RESULT,""));finish();}
}
